def resolve_record_path(s: str):
    """把用户输入的路径解析成记录目录; 找不到返回 None。

    兼容: 记录目录 / accel-25hz.csv 文件路径 / 带引号 / ~ 开头 /
    相对当前目录或相对项目根的相对路径。
    """
    p = Path(s).expanduser()
    # 依次按"原样"和"相对项目根"两个基准找。
    for c in (p, ROOT / p):
        if c.is_file():
            # 给的是 CSV 文件路径 → 记录目录就是它所在的文件夹。
            return c.parent
        if c.is_dir() and (c / ACC_FILE).is_file():
            return c
    return None


